def dt(key: str, language: str = "en") -> str:
    row = _ROWS.get(key)
    if row is None:
        return key
    return row[LANGS.index(language) if language in LANGS else 1]


def install_catalogue() -> None:
    """Make the same text available to the existing live language switcher."""
    from jarvis import i18n
    catalogue = getattr(i18n, "EXACT", None)
    if isinstance(catalogue, dict):
        for row in _ROWS.values():
            catalogue[row[0]] = dict(zip(LANGS[1:], row[1:]))
